// Generated from training/small-molecule-course.json.
const CATALOG = {"categories":[{"id":"target","title":"Target identification & validation","description":"Connect a disease question to a testable therapeutic hypothesis."},{"id":"hits","title":"Hit discovery","description":"Find activity. Establish what the assay actually tells you."},{"id":"leads","title":"Hit to lead","description":"Turn a confirmed hit into a useful chemical starting point."},{"id":"candidate","title":"Lead optimization & candidate selection","description":"Connect exposure, biological effects, and the decision to advance."},{"id":"nonclinical","title":"IND-enabling nonclinical studies","description":"Build evidence for the proposed population and regimen."},{"id":"cmc","title":"Chemistry, manufacturing & controls","description":"Define and control the material that people will receive."},{"id":"clinical","title":"Clinical & regulatory planning","description":"Turn evidence into a first-study plan and focused decisions."},{"id":"ind","title":"IND submission & review","description":"Assemble the evidence, navigate review, and prepare to start."}],"levels":[{"id":"target-question","category":"target","title":"Start With the Disease","goal":"Define the disease state and biological change that the program intends to influence.","concept":"Before choosing a target, specify the problem the intervention should change: which patients, which disease state, which tissue, and which function. A molecular feature associated with disease can suggest a hypothesis, but the desired intervention is a separate claim. This distinction helps you choose relevant models and measurements. Discovery can begin with a target or a phenotype; either route needs a clear therapeutic question.","takeaway":"Name the disease problem before treating a molecular association as a treatment strategy.","exampleTitle":"Preventing fibrosis or reversing it?","example":"Invented example: a team finds a strong matrix-production signature in tissue from advanced fibrotic disease. It proposes blocking the highest-ranked enzyme. Yet its assay only measures new matrix deposition after an injury stimulus. That assay could inform prevention of further deposition; it does not directly test removal of established scar. The team separates these questions before choosing which patient state and model to study.","worked":"The assay addresses new matrix formation; reversal of established fibrosis remains a different hypothesis.","diagram":[["Disease question","Prevent new matrix or remove existing scar?"],["Model question","Which of those changes does the assay measure?"]],"exampleSteps":[["Observe","Advanced tissue has a matrix-related signature."],["Inspect","The assay measures newly deposited matrix."],["Bound the claim","Prevention evidence does not establish scar reversal."]],"question":{"title":"Match the claim to the experiment","prompt":"A compound reduces an injury marker when added before the injury stimulus. What remains untested?","options":[["Whether the compound changed the measured marker","The experiment already observed that change under the tested conditions.",false],["Whether treatment after established injury improves function","Correct. Prevention and treatment of established injury differ in timing and biological context.",true],["Whether the target deserves any further investigation","The result can justify follow-up even though it does not answer every therapeutic question.",false]],"hint":"Compare when treatment began with when you intend to treat patients."},"sources":[{"label":"NCATS: Discovery of a therapeutic approach","url":"https://toolkit.ncats.nih.gov/module/getting-started/understand-the-rd-process/discovery-of-therapeutic-approach/"}]},{"id":"target-prioritization","category":"target","title":"Prioritize Evidence, Not Rankings","goal":"Use complementary evidence to prioritize a target and identify the uncertainty that matters next.","concept":"Target prioritization combines evidence about disease relevance, the direction of intervention, experimental tractability, and potential liabilities. Genetics, expression, perturbation studies, and prior pharmacology answer different questions. Several correlated datasets can repeat one association rather than provide independent support. A computational rank is useful for organizing candidates, but the underlying evidence and its gaps should determine which experiment receives the next investment of time.","takeaway":"Use a ranking to find candidates, then inspect why each candidate ranks highly.","exampleTitle":"Two targets, different evidence","example":"Invented example: target A has the largest expression change across three datasets collected from overlapping patient cohorts. Target B has a smaller expression change, but independent perturbation experiments improve a relevant cellular function. Neither is automatically the winner. The team notes that A's evidence is partly redundant and asks whether altering A changes function, while checking whether B's experimental effect survives a more relevant disease context.","worked":"Evidence diversity and the next discriminating experiment matter more than expression rank alone.","diagram":[["High rank","Which data and assumptions produced it?"],["Useful priority","Which uncertainty is worth resolving next?"]],"exampleSteps":[["Compare","A has strong expression evidence; B has functional evidence."],["Check independence","A's cohorts partly overlap."],["Choose follow-up","Test causal function and disease-context relevance."]],"question":{"title":"Audit an AI target list","prompt":"An AI tool ranks one target first, citing five papers that all reuse the same patient dataset. What is the most useful next step?","options":[["Count the five papers as five independent replications","Shared underlying samples can make apparently separate results dependent.",false],["Discard the target because computational prioritization is uninformative","The ranking can still identify a useful hypothesis; its evidence needs inspection.",false],["Trace the shared data and seek complementary functional evidence","Correct. Inspect provenance, then ask for evidence that addresses a different part of the causal claim.",true]],"hint":"Five references do not necessarily mean five independent experiments."},"sources":[{"label":"Koscielny et al.: Open Targets evidence integration","url":"https://pubmed.ncbi.nlm.nih.gov/27899665/"},{"label":"NCATS: Disease and therapeutic approach","url":"https://toolkit.ncats.nih.gov/module/getting-started/understand-the-rd-process/discovery-of-therapeutic-approach/"}]},{"id":"target-validation","category":"target","title":"Test Causality With Perturbations","goal":"Distinguish a target-associated phenotype from evidence that altering the target causes that phenotype.","concept":"Causal validation asks whether changing the target produces the relevant effect under defined conditions. Independent perturbations and appropriate controls help separate the intended change from reagent artifacts or general cell stress. Rescue can strengthen attribution when restoring a functional, perturbation-resistant target restores the phenotype. Its design still matters. Genetic depletion and a drug's partial, time-dependent inhibition need not create identical biological states.","takeaway":"Confirm the perturbation, challenge alternative explanations, and keep the conclusion specific to the model.","exampleTitle":"A knockdown with a rescue","example":"Invented example: two distinct siRNAs lower protein Q and reduce a stimulated inflammatory readout in human cells without reducing cell number. Re-expression of functional, siRNA-resistant Q restores the readout, while an empty-vector control does not. This supports Q's causal role in that model. It does not yet show that a selective small molecule can reproduce the effect at a tolerable exposure in people.","worked":"Independent perturbations plus a controlled rescue strengthen target attribution within the tested system.","diagram":[["Perturb Q","Does the relevant phenotype change?"],["Restore Q","Does the phenotype return under controlled conditions?"]],"exampleSteps":[["Perturb","Distinct siRNAs lower Q and the inflammatory readout."],["Challenge attribution","Restore functional Q using a resistant construct."],["Interpret","Model causality is supported; drug feasibility remains open."]],"question":{"title":"What does knockdown establish?","prompt":"One siRNA reduces both target protein and cell survival. Which follow-up most directly tests whether target loss explains the survival effect?","options":[["Use independent perturbations and a controlled target-rescue experiment","Correct. These challenge sequence-specific artifacts and test whether restoring target function changes the phenotype.",true],["Measure target mRNA again with more technical replicates","That may improve precision but does not establish that target loss caused reduced survival.",false],["Assume the survival effect is on-target because protein levels fell","An siRNA can lower its intended target and also have other effects.",false]],"hint":"Target knockdown and phenotype can occur together without the former causing the latter."},"sources":[{"label":"Assay Guidance Manual: RNAi validation and rescue","url":"https://www.ncbi.nlm.nih.gov/books/NBK91998/?report=classic"},{"label":"Huang et al.: Complementary genetic and pharmacological target tests","url":"https://pubmed.ncbi.nlm.nih.gov/28926338/"}]},{"id":"target-hypothesis","category":"target","title":"Write a Therapeutic Hypothesis","goal":"Connect target modulation to an intended benefit and a testable concern about normal biology.","concept":"A therapeutic hypothesis connects an intervention to a useful outcome: modulating this target, in this direction and biological context, should change this disease process. Include the conditions that could make the idea fail, such as inadequate tissue access or disruption of normal function. This gives experiments a purpose. It is a revisable scientific proposal, not a claim that the target or eventual drug is clinically validated.","takeaway":"State both the expected benefit and the biological condition that could limit it.","exampleTitle":"Useful inhibition has conditions","example":"Invented example: enzyme R supports excessive matrix production in activated fibroblasts, but also contributes to normal repair. The team's hypothesis is that partial inhibition during persistent activation will reduce new pathological matrix while preserving enough repair capacity. It therefore measures matrix production and repair function across exposure and time. A lower matrix signal alone would not settle the hypothesis if normal repair declined alongside it.","worked":"The hypothesis becomes informative when benefit and the anticipated normal-function liability are tested together.","diagram":[["Intended benefit","Reduce pathological matrix production"],["Limiting condition","Retain sufficient normal repair function"]],"exampleSteps":[["Specify intervention","Partial R inhibition during persistent activation."],["Measure both sides","Pathological matrix and normal repair function."],["Revise if needed","Benefit without usable separation changes the strategy."]],"question":{"title":"Make the proposal testable","prompt":"Which statement is the strongest therapeutic hypothesis for the next experiments?","options":[["R is highly expressed, so inhibiting it will treat fibrosis","Expression suggests a relationship but does not establish the consequence of inhibition.",false],["Partial R inhibition may reduce pathological matrix while preserving repair; measure both across exposure","Correct. The proposal specifies direction, benefit, a limiting condition, and evidence that can challenge it.",true],["Any molecule that binds R should become a clinical candidate","Binding alone leaves functional activity, exposure, safety, and product feasibility unresolved.",false]],"hint":"Look for a claim that could be changed by a clearly specified result."},"sources":[{"label":"Assay Guidance Manual: Therapeutic hypotheses in early discovery","url":"https://www.ncbi.nlm.nih.gov/books/NBK92015/"}]},{"id":"hits-assay","category":"hits","title":"Choose What the Assay Measures","goal":"Match the primary assay's readout to the biological question and anticipate alternative causes of its signal.","concept":"An assay converts biology into a measurable signal, and the conversion can introduce alternative explanations. A biochemical assay can isolate an interaction; a cellular phenotype can preserve more biological context while leaving mechanism less resolved. Choose the format for the question and plan controls around its vulnerabilities. An orthogonal measurement changes the detection approach to test whether activity depends on the original readout technology.","takeaway":"Know what changes the signal before interpreting what the compound changes in biology.","exampleTitle":"A dimmer reporter is ambiguous","example":"Invented example: a luciferase reporter tracks an inflammatory pathway. Compound H lowers luminescence, but that could reflect pathway inhibition, interference with the reporter enzyme, or loss of viable cells. The team adds a reporter-interference test, a cell-health measurement, and a different readout of pathway activity. Together these distinguish explanations that the primary luminescence value cannot separate on its own.","worked":"A lower reporter signal is an observation; pathway inhibition is one explanation to test.","diagram":[["Observed signal","Luminescence decreases"],["Competing explanations","Pathway effect, reporter interference, or cell loss"]],"exampleSteps":[["Define readout","Reporter luminescence reflects several possible processes."],["Add controls","Test reporter interference and cell health."],["Cross-check biology","Use a different pathway readout."]],"question":{"title":"Choose the complementary measurement","prompt":"A hit lowers a fluorescent pathway reporter. Which experiment most directly tests whether the biological effect survives changing the detection method?","options":[["Repeat the same reporter measurement at higher instrument gain","This changes instrument settings but retains the same basic detection vulnerability.",false],["Select the compounds with the brightest intrinsic fluorescence","Intrinsic fluorescence may interfere with the assay and does not confirm pathway activity.",false],["Measure the same pathway response with an independently validated detection method","Correct. An orthogonal readout tests dependence on the original detection method; mechanism may still need further work.",true]],"hint":"Change the way you observe the biology while retaining the biological question."},"sources":[{"label":"Assay Guidance Manual: Assay design and validation","url":"https://www.ncbi.nlm.nih.gov/books/NBK92019/"},{"label":"Assay Guidance Manual: Reporter interference and orthogonal assays","url":"https://www.ncbi.nlm.nih.gov/books/NBK374281/"}]},{"id":"hits-screening","category":"hits","title":"Screen With Interpretable Controls","goal":"Interpret initial screen activity using controls, plate behavior, and the conditions of measurement.","concept":"A screen identifies samples worth investigating under its tested conditions. Positive and negative controls, plate patterns, and repeatability help distinguish compound effects from assay behavior. A hit threshold is an operational choice informed by assay performance, not a universal biological boundary. Screening can use different library sizes and concentration designs. An initial active result starts a follow-up question; it does not establish selectivity, mechanism, or therapeutic value.","takeaway":"Read the controls and plate behavior before trusting a ranked hit list.","exampleTitle":"The active edge of a plate","example":"Invented example: a screen produces a cluster of apparent inhibitors in the outer wells of several plates. Control wells in the same region also show a lower signal. Rather than celebrating a chemically diverse hit set, the team investigates handling and positional effects, then retests selected compounds in different positions. If the signal follows the well location rather than the compound, the initial ranking needs reinterpretation.","worked":"Activity that tracks plate position can reflect assay behavior rather than a compound-specific effect.","diagram":[["Compound hypothesis","Activity follows the sample"],["Assay hypothesis","Activity follows position or handling"]],"exampleSteps":[["Inspect","Apparent hits cluster in outer wells."],["Compare controls","Regional control signals also decrease."],["Retest","Change sample positions and investigate handling."]],"question":{"title":"What deserves investigation first?","prompt":"Most apparent hits come from one plate, whose negative controls also shifted. What is the most informative next action?","options":[["Investigate that plate's performance and repeat relevant samples with appropriate controls","Correct. First determine whether the unusual signal is attributable to the compounds or the assay run.",true],["Prioritize that plate because it contains the largest number of actives","A shifted control distribution can inflate apparent activity.",false],["Delete every hit from the entire screen permanently","The evidence flags a run-quality question, not proof that all compounds are inactive.",false]],"hint":"A compound effect should be interpreted against controls that behaved as expected."},"sources":[{"label":"Assay Guidance Manual: HTS assay validation and plate uniformity","url":"https://www.ncbi.nlm.nih.gov/books/NBK83783/"},{"label":"Assay Guidance Manual: Image-based screening and assay performance","url":"https://www.ncbi.nlm.nih.gov/books/NBK100913/"}]},{"id":"hits-confirmation","category":"hits","title":"Confirm the Chemical Hit","goal":"Connect reproducible biological activity to characterized chemical material before relying on the hit.","concept":"Hit confirmation asks whether reproducible activity belongs to the intended compound under interpretable conditions. Retesting across concentrations, checking material identity and purity, and using suitable complementary assays address different failure modes. A reproducible curve can still reflect an impurity or assay interference. Fresh material or resynthesis can clarify attribution when needed. The appropriate characterization depends on the material and project; no single universal assay battery settles every hit.","takeaway":"Confirm both the activity and the chemical material responsible for it.","exampleTitle":"The original vial was active","example":"Invented example: a library sample gives a reproducible concentration-response curve, but a freshly sourced, identity-checked sample of the labeled compound is inactive in the same assay. The team compares purity, concentration, handling, and stability rather than immediately choosing its preferred result. An active impurity or degraded sample is possible, but so is a problem with the new preparation. The discrepancy needs resolution before confident SAR interpretation.","worked":"A sample-level result cannot yet be assigned confidently to the labeled molecular structure.","diagram":[["Biological confirmation","Does activity reproduce under suitable conditions?"],["Chemical confirmation","What material actually produced that activity?"]],"exampleSteps":[["Retest","The original library sample remains active."],["Compare material","Fresh labeled compound gives a different result."],["Resolve discrepancy","Inspect identity, purity, concentration, handling, and stability."]],"question":{"title":"Interpret disagreement between samples","prompt":"The original hit sample is active, but a new preparation is inactive. Which conclusion is justified now?","options":[["The labeled compound is confirmed because the original curve repeated","Reproducibility does not identify which chemical component produced the activity.",false],["The activity's chemical attribution remains unresolved and the preparations should be compared","Correct. Characterize and compare the materials and assay conditions before assigning the effect.",true],["Discard the entire series before comparing the preparations","A material discrepancy warrants investigation; it does not yet eliminate the intended structure or related series.",false]],"hint":"Separate the structure written on the vial from the substance tested in the well."},"sources":[{"label":"Assay Guidance Manual: Small-molecule identity and purity, 2026","url":"https://www.ncbi.nlm.nih.gov/books/NBK623671/"},{"label":"Assay Guidance Manual: Hit confirmation","url":"https://www.ncbi.nlm.nih.gov/books/NBK92015/"}]},{"id":"hits-mechanism","category":"hits","title":"Connect Binding to Biology","goal":"Distinguish target interaction from evidence that the interaction explains the cellular phenotype.","concept":"Mechanism evidence links a compound's interaction with a target to a biological effect. Biochemical binding, cellular target engagement, pathway responses, and phenotype are different observations. Their concentration and time relationships should make biological sense. Genetic or pharmacological controls can test whether the proposed target mediates the effect. A phenotypic program can advance mechanistic understanding iteratively; complete mechanism resolution is not a universal prerequisite for every discovery activity.","takeaway":"Binding names a possible interaction; causal evidence connects that interaction to the effect you care about.","exampleTitle":"A binder with a phenotype","example":"Invented example: compound H binds purified protein Q and reduces a cellular inflammatory response. A cellular engagement assay supports interaction with Q at active concentrations. Cells expressing a functional, H-resistant Q variant retain the inflammatory response during treatment, while matched control cells do not. These findings strengthen Q-mediated attribution, assuming the variant and controls behave appropriately. They do not show that H interacts with no other proteins.","worked":"Engagement plus a controlled resistance experiment links Q to the phenotype more strongly than binding alone.","diagram":[["Interaction evidence","The compound engages Q in cells"],["Causal evidence","Changing Q's sensitivity changes the phenotype"]],"exampleSteps":[["Observe interaction","H binds Q and engages it in cells."],["Challenge mechanism","Test a functional H-resistant Q variant."],["Bound the claim","Q-mediated activity is supported; exclusive selectivity is not."]],"question":{"title":"Use a computational prediction well","prompt":"Docking predicts that a phenotypic hit binds protein K, but there is no experimental interaction or dependence evidence. What best advances the mechanism question?","options":[["Call K the confirmed target because the docking score is favorable","A predicted pose or score does not establish binding or explain the phenotype.",false],["Treat a matching expression signature as definitive proof of direct binding","A downstream signature can arise through multiple upstream mechanisms.",false],["Test interaction in an appropriate experimental system and whether K mediates the phenotype","Correct. The prediction generates a testable hypothesis; interaction and causal attribution need complementary evidence.",true]],"hint":"Ask separately whether the compound interacts with K and whether that interaction explains its effect."},"sources":[{"label":"Martinez Molina et al.: Measuring target engagement in cells and tissues","url":"https://pubmed.ncbi.nlm.nih.gov/23828940/"},{"label":"Huang et al.: Testing target dependence with complementary methods","url":"https://pubmed.ncbi.nlm.nih.gov/28926338/"},{"label":"Assay Guidance Manual: Phenotypic profiling and mechanism hypotheses","url":"https://www.ncbi.nlm.nih.gov/books/NBK100913/"}]},{"id":"sar-tradeoffs","category":"leads","title":"Read the Whole SAR","goal":"Separate a measured potency improvement from a broader improvement in the compound.","concept":"A structure–activity relationship is useful when the chemical change and the measured effect can be interpreted together. A better biochemical IC50 establishes an improvement under that assay's conditions, not automatically inside cells. Compare matched experiments and their variability before attributing a cellular difference to permeability, binding, metabolism, or mechanism. The next experiment should distinguish those explanations rather than reward the smallest number.","takeaway":"An improved assay result supports a specific claim, not every desirable property.","exampleTitle":"A stronger enzyme inhibitor","example":"Invented example: replacing a peripheral group changes biochemical IC50 from 30 to 3 nM. In a matched cellular pathway assay, the values are 300 and 280 nM, within normal assay variability. Repeated experiments confirm the biochemical shift. The team has improved enzyme inhibition under those conditions, but has not established better cellular activity or explained why the gain fails to translate.","worked":"The supported gain is biochemical potency; cellular exposure or mechanism experiments can investigate the missing translation.","diagram":[["Biochemical IC50","30 → 3 nM"],["Cellular pathway IC50","300 → 280 nM"]],"exampleSteps":[["Change the structure","Replace one peripheral group."],["Compare matched assays","The biochemical change repeats; the cellular difference is within variability."],["Limit the claim","Investigate cellular exposure and mechanism before claiming a better cellular compound."]],"question":{"title":"Which improvement is established?","prompt":"The biochemical shift repeats, while the cellular difference remains within assay variability. What can you conclude?","options":[["Biochemical potency improved under the tested conditions.","Correct. The experiment supports that bounded claim; improved cellular activity and its explanation remain unestablished.",true],["Cell permeability must have improved.","No. Neither the biochemical result nor the small cellular difference establishes permeability.",false],["The analog will require a lower human dose.","No. Human dose depends on exposure, effects, safety and other evidence not measured here.",false]],"hint":"Name the property the experiment actually measured."},"sources":[{"label":"NIH Assay Guidance Manual: mechanism and assay-dependent activity","url":"https://www.ncbi.nlm.nih.gov/books/NBK92001/"}]},{"id":"selectivity-context","category":"leads","title":"Selectivity Is Context Dependent","goal":"Explain why a selectivity result cannot by itself establish safety.","concept":"Selectivity describes differences in activity across the targets, assays, and conditions actually tested. It is not a certificate that a molecule has no other effects. A selective inhibitor can also disrupt its intended target in normal tissue. Interpret a panel alongside relevant concentrations and biological context, and distinguish an observed injury from evidence establishing whether that injury is on-target or off-target.","takeaway":"Selectivity narrows a mechanism question; it does not eliminate all possible harm.","exampleTitle":"A clean panel, an unanswered risk","example":"Invented example: compound S inhibits XYZ1 at 10 nM and a related enzyme at 1,000 nM in comparable biochemical assays. In human intestinal organoids, barrier function declines at concentrations that also suppress the XYZ1 pathway. The panel describes a measured selectivity difference. It does not exclude injury from normal XYZ1 function, and the organoid association alone does not prove that mechanism.","worked":"Treat on-target intestinal injury as a hypothesis requiring follow-up, not as either excluded or conclusively established.","diagram":[["Tested enzyme selectivity","XYZ1: 10 nM · related enzyme: 1,000 nM"],["Normal-tissue observation","Pathway suppression accompanies barrier injury"]],"exampleSteps":[["Read the panel","Selectivity applies to the measured targets and assay conditions."],["Inspect the tissue","Normal intestinal biology may depend on the intended target."],["Test causality","Use complementary perturbations or rescue evidence to investigate the injury."]],"question":{"title":"Why is the panel insufficient?","prompt":"What is the strongest reason the enzyme selectivity result cannot establish intestinal safety?","options":[["Biochemical selectivity results never provide useful information.","No. The panel provides useful information about measured activity differences; its scope is limited.",false],["The organoid result proves the injury is off-target.","No. The association does not establish whether the injury is on-target, off-target, or mixed.",false],["It does not exclude harm from inhibiting XYZ1 in normal tissue.","Correct. Selectivity against another enzyme does not protect tissues that need XYZ1; causality still needs investigation.",true]],"hint":"Consider the intended target's role outside diseased cells."},"sources":[{"label":"NIH Assay Guidance Manual: limits of counterscreens and selectivity evidence","url":"https://www.ncbi.nlm.nih.gov/books/NBK326709/"},{"label":"FDA training: primary and secondary pharmacology","url":"https://www.fda.gov/media/185123/download"}]},{"id":"early-adme","category":"leads","title":"Interpret Early ADME Signals","goal":"Choose follow-up experiments that distinguish causes of low oral exposure.","concept":"Early absorption, distribution, metabolism, and excretion experiments help explain how a molecule reaches and leaves relevant compartments. Low plasma exposure after oral dosing can reflect limited absorption, presystemic metabolism, rapid systemic clearance, or combinations of these. One screening result rarely identifies the dominant cause. Integrate formulation observations, in-vitro measurements, and appropriately designed PK experiments before deciding which property to optimize.","takeaway":"Diagnose an exposure limitation before choosing its solution.","exampleTitle":"Low exposure, competing explanations","example":"Invented example: compound D produces low mouse plasma exposure after a 10 mg/kg oral dose. It dissolves slowly in a formulation test, while mouse liver microsomes also metabolize it rapidly. Either observation could matter. The team plans oral and intravenous PK with suitable formulations and comparable conditions, alongside further solubility work, instead of assuming that another absorption aid will solve the problem.","worked":"Oral and intravenous PK can help assess systemic clearance and oral availability, but additional evidence may be needed to separate absorption from first-pass loss.","diagram":[["Oral PK observation","Low measured plasma exposure"],["Possible contributors","Absorption · first-pass loss · systemic clearance"]],"exampleSteps":[["Observe the problem","Low exposure follows oral dosing."],["Keep alternatives open","Slow dissolution and rapid metabolic turnover suggest different contributors."],["Discriminate","Combine suitable oral/IV PK with targeted in-vitro follow-up."]],"question":{"title":"Which next step is most informative?","prompt":"Slow dissolution and rapid microsomal turnover accompany low oral plasma exposure. Which plan best separates the possibilities?","options":[["Optimize dissolution and assume exposure will be adequate.","No. Dissolution may contribute, but metabolism or systemic clearance could still limit exposure.",false],["Combine suitable oral/IV PK with targeted solubility and metabolism follow-up.","Correct. These complementary experiments can distinguish contributors instead of treating one screening result as the complete explanation.",true],["Abandon the compound because low plasma exposure proves low exposure in every tissue.","No. Plasma and tissue exposure are not interchangeable, and the cause may be addressable.",false]],"hint":"Choose experiments that distinguish explanations, not merely repeat the observation."},"sources":[{"label":"FDA: pharmacology, drug disposition and IND information","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-pharmacology-and-toxicology-pt-information"},{"label":"FDA training: PK, ADME and toxicokinetics","url":"https://www.fda.gov/media/185123/download"}]},{"id":"balanced-lead","category":"leads","title":"Choose a Balanced Lead","goal":"Prioritize a lead for a defined next experiment using several relevant properties.","concept":"Lead selection is a decision about the next development objective, not a universal ranking by potency. Compare the properties that determine whether the planned experiment can answer its question, including exposure, formulation feasibility, selectivity, and emerging liabilities. State which evidence is measured and which is predicted. A defensible choice includes the trade-off, remaining uncertainty, and a reason to revisit the decision.","takeaway":"Choose for the next objective, and make the trade-off explicit.","exampleTitle":"Potency versus a usable experiment","example":"Invented example: lead A has a cellular IC50 of 5 nM but precipitates in the tested oral formulation and gives highly variable exposure. Lead B has an IC50 of 30 nM, remains dispersed, and produces reproducible exposure. The immediate goal is an interpretable oral PK/PD experiment. Neither lead has a definitive safety package, and A remains available for further chemistry or formulation work.","worked":"Prioritizing B for this experiment is defensible because its current profile better supports interpretation, not because less potent compounds are generally preferable.","diagram":[["Lead A","5 nM · variable exposure"],["Lead B","30 nM · reproducible exposure"]],"exampleSteps":[["Define the objective","Run an interpretable oral PK/PD experiment."],["Compare relevant evidence","Exposure reproducibility matters alongside cellular potency."],["Preserve uncertainty","Prioritize B for this step while retaining A and documenting unresolved risks."]],"question":{"title":"Which selection rationale is defensible?","prompt":"For the immediate oral PK/PD experiment, which justification follows from these data?","options":[["Prioritize B for the experiment and document the remaining gaps.","Correct. This matches the choice to the current objective without claiming B is already the development candidate.",true],["Choose A because the lowest IC50 always determines the best lead.","No. Potency cannot compensate automatically for an experiment made uninterpretable by variable exposure.",false],["Nominate B and treat its reproducible exposure as proof of safety.","No. Reproducible exposure improves interpretation; it does not establish an acceptable safety profile.",false]],"hint":"Separate choosing the next experiment from choosing a final development candidate."},"sources":[{"label":"FDA: moving from a viable candidate to evidence supporting human investigation","url":"https://www.fda.gov/drugs/types-applications/investigational-new-drug-ind-application"}]},{"id":"exposure","category":"candidate","title":"Dose Is Not Exposure","goal":"Reassess exposure and its safety support when formulation changes at the same administered dose.","concept":"Dose is the amount administered. Exposure describes drug concentration over time in a specified compartment. Bioavailability is the fraction of a dose reaching systemic circulation; for an oral drug it reflects absorption and presystemic loss. AUC, the area under a concentration–time curve, measures exposure over a stated interval. The same administered dose can produce different exposure, so its safety interpretation may change.","takeaway":"When exposure changes, revisit the evidence supporting the regimen.","exampleTitle":"Same dose. More drug reaches circulation.","example":"In the simplified model below, changing bioavailability from 50% to 100% doubles initial concentration and AUC when the other assumptions stay fixed. The dose has not changed. This illustrates why a new formulation can change the exposure that a safety assessment must address. It does not tell us whether the new exposure is effective or tolerable.","worked":"The same dose now produces more exposure. Compare that exposure with the supporting evidence before carrying an earlier safety conclusion forward.","diagram":[["Dose","Amount administered"],["Exposure","Concentration over time"]],"exampleSteps":[["Hold dose constant","Both formulations deliver 10 mg/kg orally."],["Measure what changes","Total plasma AUC0–24 increases threefold; other relevant metrics also need review."],["Reassess support","Compare exposure and safety findings, then assess regimen or bridging needs."]],"question":{"title":"The formulation changed","prompt":"A new oral formulation increases exposure at the same administered dose. What is the best next step?","options":[["Keep the old safety conclusion because the administered dose is unchanged.","No. The body can experience a different concentration-time profile at the same dose.",false],["Compare the new exposure with the safety evidence and reassess the regimen or bridging needs.","Correct. The relevant question is whether the existing evidence supports the changed exposure and material, not merely the same mg/kg dose.",true],["Automatically repeat every toxicology study before examining the existing data.","No. First assess the change and the existing evidence; the appropriate bridging work depends on what remains unsupported.",false]],"hint":"Follow the concentration-time profile, then ask which safety evidence applies."},"sources":[{"label":"FDA training: PK, exposure and toxicokinetics","url":"https://www.fda.gov/media/185123/download"},{"label":"FDA: clinical and toxicology material differences","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-chemistry-manufacturing-and-control-cmc-information"}]},{"id":"exposure-pd","category":"candidate","title":"Connect Exposure to Effects","goal":"Use measured PD duration to refine an exposure hypothesis without assuming clinical benefit.","concept":"PK describes drug exposure, while PD measures biological effects associated with treatment. Their relationship must be investigated rather than assumed: an effect may lag behind concentration or persist after concentrations decline. A downstream pathway measurement is not automatically a direct measurement of target engagement. Use matched sampling and a clear biological question to connect exposure, effect magnitude, and duration.","takeaway":"Measure the effect as well as the exposure.","exampleTitle":"One hour or eight?","example":"Invented example: two reversible inhibitors are tested at the same oral mouse dose. A matched tumor assay shows more than 80% pathway suppression for one hour with A and eight hours with B. Independent experiments suggest that prolonged suppression matters for this tumor biology. B merits further investigation under this regimen, but eight hours has not yet been shown sufficient for tumor control or tolerable dosing.","worked":"B supports longer measured pathway suppression under the tested conditions; efficacy and tolerability still require evaluation.","diagram":[["Compound A","Pathway suppression >80% for 1 hour"],["Compound B","Pathway suppression >80% for 8 hours"]],"exampleSteps":[["State the biological need","Independent evidence suggests prolonged suppression matters."],["Measure PD over time","The matched assay shows different durations at this regimen."],["Bound the conclusion","Investigate B further without equating PD with efficacy or safety."]],"question":{"title":"What does the PD result support?","prompt":"Given the stated need for prolonged suppression, which conclusion is best supported?","options":[["B must bind XYZ1 more tightly than A.","No. A downstream PD duration does not establish a direct binding-affinity difference.",false],["A's shorter PD proves poor oral absorption.","No. Many processes can influence effect duration; this experiment does not isolate absorption.",false],["B provides longer measured pathway suppression at this regimen and merits further study.","Correct. That is the measured advantage; its sufficiency for tumor control and acceptable toxicity remains unresolved.",true]],"hint":"Stay with the measured biological effect and the tested regimen."},"sources":[{"label":"FDA/NIH BEST: pharmacodynamic and response biomarkers","url":"https://www.fda.gov/drugs/biomarker-qualification-program/about-biomarkers-and-qualification"},{"label":"FDA: exposure–response study design","url":"https://www.fda.gov/media/71277/download"}]},{"id":"efficacy-models","category":"candidate","title":"Read Efficacy Models Carefully","goal":"State which biological and treatment context an efficacy experiment supports.","concept":"An efficacy model tests an intervention in a particular biological system under particular treatment conditions. Its value depends on the question, controls, exposure, endpoints, and features shared with the intended patient population. A positive result can strengthen a development rationale without establishing general clinical benefit. Ask which assumptions would need to hold for the observation to transfer beyond the model.","takeaway":"Carry the model's evidence forward together with its limitations.","exampleTitle":"A responsive tumor model","example":"Invented oncology example: drug E reduces a human tumor xenograft's volume by 45% from baseline over 21 days, while vehicle controls grow. Tumor pathway suppression is measured during treatment. The host mice are immunodeficient, and the implanted cells were selected for high XYZ1 expression. The result supports activity in this setting; it does not establish responses across heterogeneous human tumors or an intact immune system.","worked":"Use the result to define a testable clinical rationale and the biological variation that further experiments should examine.","diagram":[["Observed activity","Regression in one selected xenograft model"],["Unresolved transfer","Tumor diversity · immune context · human treatment conditions"]],"exampleSteps":[["Identify the observation","Controlled tumor regression accompanies measured pathway suppression."],["Identify the model boundaries","Selected cells and immunodeficient hosts constrain the inference."],["Choose informative follow-up","Test relevant biological variation with interpretable exposure and PD measurements."]],"question":{"title":"What would broaden the evidence?","prompt":"Which follow-up most directly examines whether the finding extends beyond the selected model?","options":[["Study relevant biological variation while measuring exposure and PD.","Correct. This tests the boundary of the current inference; the exact model choice should follow the intended clinical question.",true],["Only increase the sample size in the same model and claim broad clinical relevance.","No. More animals may improve precision in that model, but do not by themselves address its biological limits.",false],["Treat the regression percentage as the predicted human response rate.","No. A model's tumor-volume change is not a prediction of the proportion of patients who will respond.",false]],"hint":"Distinguish precision within a model from applicability beyond it."},"sources":[{"label":"FDA: nonclinical evidence supporting the proposed investigation","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-pharmacology-and-toxicology-pt-information"},{"label":"ICH S9: pharmacology in the advanced-cancer context","url":"https://www.fda.gov/media/73161/download"}]},{"id":"candidate-nomination","category":"candidate","title":"Nominate With Explicit Gaps","goal":"Explain candidate nomination as an internal decision with an evidence rationale and a plan.","concept":"Candidate nomination is an internal decision to advance a specific molecule into a defined development program. It integrates the available biology, exposure, safety signals, product feasibility, and intended clinical use. The decision should make unresolved questions and the work needed to address them explicit. Nomination does not itself mean that an IND is ready, that FDA has agreed, or that people may receive the drug.","takeaway":"Nomination selects the molecule and commits to the next evidence-building plan.","exampleTitle":"A nomination with visible unknowns","example":"Invented example: a team nominates compound C after reproducible oral exposure, model efficacy, and an initial safety assessment. A 20-gram synthesis is reproducible, but longer stability work and the planned repeat-dose safety studies remain unfinished. The nomination memo records why C was selected, what could overturn the choice, and who owns each next study. The decision authorizes internal development work, not human dosing.","worked":"A useful nomination record connects the selected molecule to its rationale, unresolved risks, and accountable next steps.","diagram":[["Internal decision","Advance compound C with a documented rationale"],["Separate later decision","Assess whether the package supports a proposed human study"]],"exampleSteps":[["Integrate current evidence","Review activity, exposure, safety signals and product feasibility."],["Name the gaps","Record unfinished studies, uncertainty and criteria for reconsideration."],["Assign the next work","Define responsibilities without representing nomination as FDA authorization."]],"question":{"title":"What has nomination accomplished?","prompt":"The team selects compound C while some development studies remain unfinished. What does that decision mean?","options":[["FDA has accepted C as sufficiently safe for human dosing.","No. An internal nomination is not an FDA action and does not satisfy the conditions for clinical investigation.",false],["Every uncertainty about the molecule has been resolved.","No. Development decisions often proceed with explicit remaining questions and plans to address them.",false],["The team has chosen a molecule and a justified plan for the next development work.","Correct. Nomination makes an internal choice and its rationale explicit; clinical readiness is a separate assessment.",true]],"hint":"Separate an internal program milestone from a regulatory status."},"sources":[{"label":"FDA: candidate development and the IND's purpose","url":"https://www.fda.gov/drugs/types-applications/investigational-new-drug-ind-application"}]},{"id":"clinical-plan-package","category":"nonclinical","title":"Start With the Clinical Plan","goal":"Explain how intended clinical use determines the nonclinical questions.","concept":"A nonclinical package supports a particular clinical plan. Population, route, schedule, duration, expected exposure, and existing evidence determine which risks need investigation and when. Changing that plan can change the supporting evidence needed. ICH M3(R2) provides a general framework; ICH S9 addresses anticancer development in its defined advanced-cancer context. Neither is a universal checklist of assays, species, or study durations.","takeaway":"Define the proposed human use before deciding what evidence must support it.","exampleTitle":"A longer dosing proposal","example":"In this fictional program, Kestrel-12 was studied to support a short oral trial in adults with a serious inflammatory disease. The team now proposes months of continuous dosing. Its summary still describes only the original schedule. Before extending treatment, the team maps the longer exposure and relevant patient risks against existing evidence, identifying what additional support or justification is needed.","worked":"The longer clinical schedule needs a fresh assessment of whether the evidence supports it.","diagram":[["Clinical plan","Population + route + schedule"],["Evidence plan","Risks + available support + gaps"]],"exampleSteps":[["Define","Describe the longer continuous dosing plan."],["Compare","Check which risks the existing package addresses."],["Resolve","Justify adequacy or address the remaining gaps."]],"question":{"title":"What changes the package?","prompt":"The planned trial extends treatment from days to months. What is the strongest next step?","options":[["Reassess whether existing evidence supports the longer exposure.","Correct. The package must support the revised clinical conditions.",true],["Keep the original package because the molecule is unchanged.","The molecule is unchanged, but duration can change the risk questions.",false],["Copy the study list from an unrelated cancer program.","Different indications and patient populations can require different evidence.",false]],"hint":"Start with what will change for trial participants."},"sources":[{"label":"FDA / ICH M3(R2): clinical scope and duration","url":"https://www.fda.gov/media/71542/download"},{"label":"FDA / ICH S9: defined advanced-cancer context","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/s9-nonclinical-evaluation-anticancer-pharmaceuticals"}]},{"id":"model","category":"nonclinical","title":"Check What the Model Tests","goal":"Separate evidence of tumor activity from evidence about normal-tissue risk.","concept":"A model answers only the questions its biology and drug exposure allow it to test. Tumor response can demonstrate activity in the implanted tumor while leaving effects in normal human tissues unresolved. Compare target sensitivity, pathway function, and relevant exposure before interpreting a negative safety finding. In the advanced-cancer setting, ICH S9 recommends selecting pharmacology models around the target and mechanism.","takeaway":"An unperturbed mouse pathway cannot rule out risk from perturbing the human pathway.","exampleTitle":"Tumor response, missing gut coverage","example":"In this fictional advanced-cancer study, Lumen-8 shrinks implanted human tumors in mice. The compound inhibits a human target also used by intestinal cells, but it does not inhibit the mouse version at the tested exposure. The mice show no intestinal injury. The tumor result supports activity in that tumor model; the normal mouse intestine has not tested the proposed human intestinal mechanism.","worked":"Human intestinal risk remains unresolved despite tumor response and healthy mouse intestines.","diagram":[["Human tumor","Target inhibited; tumor responds"],["Mouse intestine","Pathway unperturbed; risk question open"]],"exampleSteps":[["Observe","The implanted human tumor responds."],["Check","The mouse intestinal target is not inhibited."],["Interpret","Human intestinal risk still needs relevant evidence."]],"question":{"title":"What remains unresolved?","prompt":"Human tumors respond in mice, but the drug leaves the mouse intestinal pathway unperturbed. What follows?","options":[["The lack of mouse intestinal injury establishes human intestinal safety.","That tissue did not test the relevant pathway perturbation.",false],["Tumor shrinkage proves the drug acts only in tumors.","Tumor response does not establish selectivity across normal human tissues.",false],["Human intestinal risk remains unresolved.","Correct. The mouse intestine did not test the relevant human mechanism.",true]],"hint":"Ask whether the normal tissue experienced the mechanism that could cause harm."},"sources":[{"label":"ICH S9 §2.1: target and mechanism in model selection; advanced-cancer context","url":"https://database.ich.org/sites/default/files/S9_Guideline.pdf"},{"label":"FDA / ICH S9 Q&A: relevance of nonclinical models; advanced-cancer context","url":"https://www.fda.gov/media/100344/download"}]},{"id":"toxicology-tk-glp","category":"nonclinical","title":"Connect Findings to Measured Exposure","goal":"Distinguish the roles of toxicology, toxicokinetics, and GLP.","concept":"Toxicology identifies adverse findings, while toxicokinetics (TK) measures exposure during toxicity studies so those findings can be interpreted. A nominal dose alone does not show how much drug reached the circulation. Good Laboratory Practice (GLP) addresses study conduct and data integrity; it does not guarantee human safety. These components work together, with study design and applicable GLP expectations justified for the program.","takeaway":"Interpret the finding, the measured exposure, and the reliability of the study together.","exampleTitle":"The same dose, different exposure","example":"In a fictional toxicity study of Harbor-4, two groups receive the same nominal dose using different formulations. One group develops liver findings and has substantially higher measured exposure. A missed sampling time is documented in the study records. The team examines the exposure difference and the deviation's impact before interpreting the finding or comparing the study with expected human exposure.","worked":"The dose label alone cannot explain the finding; TK and trustworthy records matter.","diagram":[["Toxicology + TK","What happened + exposure reached"],["GLP","Traceable conduct and reliable records"]],"exampleSteps":[["Observe","Liver findings occur in the higher-exposure group."],["Investigate","Review formulation, TK results, and sampling deviation."],["Interpret","Assess clinical relevance with the evidence's limitations."]],"question":{"title":"What does TK add?","prompt":"Two groups receive the same nominal dose, but only one has liver findings. Which evidence most directly improves exposure-based interpretation?","options":[["A GLP statement by itself.","GLP supports data integrity but does not measure exposure.",false],["Measured exposure in each group, interpreted with study records.","Correct. TK helps connect the findings to systemic exposure.",true],["The fact that both dose labels match.","Equal administered doses do not ensure equal systemic exposure.",false]],"hint":"The administered amount and the amount reaching circulation can differ."},"sources":[{"label":"FDA / ICH S3A: toxicokinetics and systemic exposure","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/s3a-toxicokinetics-assessment-systemic-exposure-toxicity-studies"},{"label":"FDA: GLP scope, quality, and integrity of safety data","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/fda-bioresearch-monitoring-information/scope-and-authority"},{"label":"FDA: GLP quality assurance and study records","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/nonclinical-laboratories-inspected-under-good-laboratory-practices/1981-questions-answers-good-laboratory-practice-regulations"}]},{"id":"risk-recovery","category":"nonclinical","title":"Interpret Recovery Without Assuming Certainty","goal":"Use recovery observations to refine risk without claiming guaranteed reversibility.","concept":"Recovery evidence helps explain whether an adverse finding improves, persists, or progresses after dosing stops. Interpretation depends on the affected tissue, severity, exposure, observation period, and evidence of repair. Improvement in one measurement does not establish complete recovery or guarantee reversibility in humans. ICH S9 and its questions and answers discuss scientific recovery assessments within their defined advanced-cancer context, rather than automatic recovery groups.","takeaway":"Describe what recovered, what persisted, and what the observation period cannot resolve.","exampleTitle":"Blood markers improve, injury persists","example":"In this fictional advanced-cancer program, Cedar-6 causes liver injury in a toxicity study. After dosing stops, blood markers move toward baseline, but tissue examination still shows lesions at the final observation. The team records partial improvement and remaining injury. It considers the tissue findings, drug exposure, and follow-up period when discussing clinical monitoring and whether further evidence could address the uncertainty.","worked":"The study shows partial improvement; it does not demonstrate complete recovery.","diagram":[["Observed improvement","Blood markers move toward baseline"],["Remaining uncertainty","Lesions persist at final observation"]],"exampleSteps":[["Separate","Distinguish blood markers from tissue findings."],["Assess","Consider severity, exposure, and observation duration."],["Conclude","Report partial improvement with residual uncertainty."]],"question":{"title":"How strong is the conclusion?","prompt":"Blood markers improve after dosing stops, but lesions remain. What is the best interpretation?","options":[["Partial improvement is observed; complete recovery is not demonstrated.","Correct. The residual lesions limit the conclusion.",true],["All liver injury is reversible because the markers improved.","One improving measure cannot establish that all injury has resolved.",false],["The lesions must be permanent because they remain at the last observation.","Persistence over this interval does not establish permanence.",false]],"hint":"Keep the conclusion within the observations and their follow-up window."},"sources":[{"label":"FDA / ICH S9 Q&A §2: recovery assessment; advanced-cancer context","url":"https://www.fda.gov/media/100344/download"},{"label":"ICH S9 §2.4: recovery interpretation; advanced-cancer context","url":"https://database.ich.org/sites/default/files/S9_Guideline.pdf"}]},{"id":"substance-product","category":"cmc","title":"Distinguish Substance From Finished Product","goal":"Explain why drug substance and drug product need different quality evidence.","concept":"Drug substance is the active ingredient; drug product is the dosage form prepared for administration, including its formulation and relevant packaging. Evidence about the ingredient does not fully characterize the finished product. Formulation and manufacturing can affect delivered dose and performance. An IND therefore describes both, including the relationship between materials used in nonclinical studies and those proposed for clinical use.","takeaway":"Knowing the active ingredient is necessary but does not fully characterize the medicine administered.","exampleTitle":"One ingredient, two formulations","example":"In this fictional program, Finch-3 is supplied as a characterized powder for formulation work. The clinical team chooses an oral capsule containing that powder and excipients. The capsule blend distributes unevenly, so individual capsules contain different amounts despite the starting ingredient passing its tests. The team must address the finished capsule's manufacture and dose consistency before judging it suitable for the proposed trial.","worked":"Acceptable drug substance alone does not establish acceptable capsule quality.","diagram":[["Drug substance","Characterized active ingredient"],["Drug product","Formulated dose + relevant packaging"]],"exampleSteps":[["Identify","The powder is the active ingredient."],["Formulate","The capsule adds excipients and processing."],["Evaluate","Review the finished capsule's dose consistency."]],"question":{"title":"Which evidence is missing?","prompt":"The active ingredient passes its tests, but capsule contents vary. Which assessment addresses the immediate issue?","options":[["Repeat only the ingredient identity test.","Identity does not resolve inconsistent capsule content.",false],["Accept the capsules because the ingredient passed.","Formulation and processing introduce additional quality questions.",false],["Investigate capsule manufacture and finished-product dose consistency.","Correct. The problem arises in producing the administered dosage form.",true]],"hint":"Follow the material from ingredient to the dose a participant receives."},"sources":[{"label":"FDA: IND CMC information for drug substance and drug product","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-chemistry-manufacturing-and-control-cmc-information"},{"label":"FDA: CGMP for phase 1 investigational drugs","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/current-good-manufacturing-practice-phase-1-investigational-drugs"}]},{"id":"process-impurities","category":"cmc","title":"Trace Impurities Through the Process","goal":"Connect manufacturing changes to impurity formation, removal, and control.","concept":"A manufacturing process can introduce, create, or remove impurities. Understanding those routes helps explain which controls matter and why a process change deserves review. An overall purity number can hide a changed impurity profile. The assessment should consider the identity and amount of relevant impurities, their safety significance, and controls appropriate to the product and development stage, with applicable guidance interpreted in context.","takeaway":"Evaluate which impurities changed and why, rather than relying on one overall purity value.","exampleTitle":"A new catalyst changes the profile","example":"In this fictional program, a revised synthesis of Willow-9 uses a different catalyst and improves yield. Overall chromatographic purity resembles the previous batch, but an additional trace component appears and residual catalyst testing has not been updated. The team investigates the new component and catalyst carryover, then evaluates appropriate removal steps, analytical methods, and controls before deciding whether the revised material is suitable.","worked":"Similar overall purity does not resolve new impurity and catalyst questions.","diagram":[["Process change","Different catalyst + new trace component"],["Control review","Formation + removal + relevant testing"]],"exampleSteps":[["Trace","Map where the new component or residue could arise."],["Evaluate","Assess identity, amount, and safety relevance."],["Control","Justify removal steps and appropriate analytical controls."]],"question":{"title":"What deserves investigation?","prompt":"A new catalyst increases yield, but the impurity profile changes. What is the strongest next step?","options":[["Investigate the changed impurities and justify appropriate controls.","Correct. Process understanding connects the change to quality and safety.",true],["Accept the process because overall purity is similar.","A similar aggregate number can mask different components.",false],["Assume every newly detected trace component is unacceptable.","Detection alone does not establish its identity, risk, or acceptable control.",false]],"hint":"Ask what the process change introduced and whether the controls address it."},"sources":[{"label":"FDA / ICH Q11: process understanding and impurity reduction","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q11-development-and-manufacture-drug-substances"},{"label":"FDA: IND CMC safety questions and manufacturing information","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-chemistry-manufacturing-and-control-cmc-information"}]},{"id":"cmc","category":"cmc","title":"Read the Whole Batch Story","goal":"Distinguish purity from active content and broader batch-quality review.","concept":"A specification pairs tests with methods and acceptance criteria. Different tests answer different quality questions: chromatographic purity is not the same as active content per dose. Batch review also considers relevant records, deviations, and other quality results. IND controls evolve with development; ICH Q6A explains specification principles for marketing applications and should not be copied as a universal early-stage test list.","takeaway":"A strong purity result cannot replace active-content testing or the rest of the quality review.","exampleTitle":"High purity, too little active","example":"In this fictional batch review, Maple-5 capsules show 99.6% chromatographic area purity among detected peaks. A separate assay reports only 82% of the intended active content per capsule, below this batch's justified criterion. The high purity figure describes the detected chemical profile, not the amount delivered. The quality team investigates the assay result and batch records before making a disposition decision.","worked":"High chromatographic purity does not resolve the low active-content result.","diagram":[["Purity result","Relative detected chemical profile"],["Active-content assay","Amount of active in each dose"]],"exampleSteps":[["Distinguish","Purity and active content answer different questions."],["Compare","Check the assay against the batch's criterion."],["Review","Investigate results and records before disposition."]],"question":{"title":"Is purity enough?","prompt":"A batch has high chromatographic purity but active content below its justified criterion. What follows?","options":[["Release it because high purity establishes full quality.","Purity does not establish the intended amount of active per dose.",false],["Investigate active content and complete the quality review.","Correct. Purity cannot replace active-content or broader batch-quality review.",true],["Ignore active content because it is another name for purity.","Active content measures amount; chromatographic purity describes a different attribute.",false]],"hint":"Ask what each number actually measures."},"sources":[{"label":"FDA / ICH Q6A: specifications, assay, and impurities; marketing context","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q6a-specifications-test-procedures-and-acceptance-criteria-new-drug-substances-and-new-drug-products"},{"label":"FDA: phase 1 manufacturing quality and batch controls","url":"https://www.fda.gov/media/70975/download"}]},{"id":"stability-product-changes","category":"cmc","title":"Recheck Stability When Products Change","goal":"Explain why a formulation or packaging change can require new supporting evidence.","concept":"Stability support connects product quality to storage conditions, packaging, and the period of use. Changing a formulation or package can change degradation or performance, so assess whether existing evidence applies. For an initial phase 1 IND, support is proportionate to the proposed study; an established commercial shelf life is not expected. Relevant data and an ongoing stability plan help support use during the trial.","takeaway":"Connect every proposed storage period to evidence relevant to the actual product and package.","exampleTitle":"A smaller bottle changes exposure","example":"In this fictional program, Rowan-2 tablets remain acceptable in the original sealed bottle during the observed stability period. To simplify clinic supply, the team changes to a smaller bottle with a different closure. Early testing suggests increased moisture uptake. The team reviews package protection and relevant quality trends before assigning the new presentation the same storage period as the original one.","worked":"The original bottle's stability period cannot be transferred without assessing the new package.","diagram":[["Existing evidence","Original tablet and sealed bottle"],["Changed presentation","New closure; moisture question"]],"exampleSteps":[["Identify","The bottle and closure have changed."],["Assess","Examine moisture protection and relevant stability trends."],["Support","Justify storage conditions and period for the new presentation."]],"question":{"title":"Can the old data carry over?","prompt":"A new closure allows more moisture uptake. What should guide the proposed storage period?","options":[["The original period automatically applies because the ingredient is unchanged.","Packaging can affect stability even when the active ingredient is unchanged.",false],["A shorter period chosen without reviewing any data.","An arbitrary reduction does not establish product quality during storage.",false],["Relevant stability evidence and a justified assessment of the packaging change.","Correct. The period must be supported for the changed presentation.",true]],"hint":"The package is part of the conditions represented by stability data."},"sources":[{"label":"FDA: first-in-human small-molecule IND CMC expectations and flexibilities","url":"https://www.fda.gov/media/193163/download?attachment="},{"label":"ICH Q1A(R2): background stability principles; registration context","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/q1ar2-stability-testing-new-drug-substances-and-products"}]},{"id":"clinical","title":"The first clinical study","goal":"Turn a recognized safety concern into clear study instructions.","concept":"The clinical protocol defines objectives, participants, dose and schedule, measurements, and decision rules. Its safety plan should explain what to monitor, when, who reviews the findings, and what actions follow. The specific plan depends on the drug and proposed study.","takeaway":"A concern becomes actionable when the protocol says what the team will do.","exampleTitle":"“Monitor kidney safety” needs a plan.","example":"An animal study identifies kidney injury at higher exposures. The clinical team uses this finding with the rest of the evidence to plan relevant assessments, their timing, who reviews them, and findings that trigger interruption or further evaluation. The program determines the appropriate measures.","worked":"A safety observation informs a plan that investigators can apply consistently. No single assay, threshold, or schedule is universal.","category":"clinical","question":{"title":"Make a vague safety plan actionable.","prompt":"A draft protocol says “watch closely for liver toxicity,” with no assessment schedule or action rules. What addresses the gap?","options":[["Specify relevant assessments, timing, review responsibilities, and justified action rules.","These instructions tell the team what to measure and how to act on the findings.",true],["Add a longer description of the target’s molecular biology.","Mechanism can inform risk, but a longer explanation does not supply the missing study instructions.",false],["Let each site invent its own monitoring plan after enrollment.","That leaves safety-critical decisions unspecified. Define the plan before conducting the study.",false]],"hint":"Could two sites read that sentence and make different safety decisions?"},"diagram":[["Safety concern","What could happen?"],["Protocol","What will the team do?"]],"exampleSteps":[["Finding","Kidney injury at higher exposures"],["Plan","Assessments, timing, reviewer"],["Action","Justified interruption or evaluation rules"]],"sources":[{"label":"FDA: clinical protocols","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-clinical-protocols"}]},{"id":"clinical-dose","category":"clinical","title":"Justifying a first dose","goal":"Explain why a starting dose needs a context-specific rationale.","concept":"A first human dose is a justified starting point for learning. Its rationale integrates relevant toxicology, pharmacology, and exposure information with the proposed population and regimen. The applicable framework matters: FDA’s adult healthy-volunteer guidance has a defined scope; it is not a universal recipe for patients with advanced cancer.","takeaway":"Choose the dosing framework for the study context before interpreting the calculations.","exampleTitle":"A mouse efficacy dose is not a human starting dose.","example":"A discovery team proposes the same milligrams per kilogram in humans that slowed tumor growth in mice. The development team asks how that relates to toxicity findings, pharmacology, predicted human exposure, and the intended participants. A direct dose match supplies none of those connections. The first-dose rationale must address them together.","worked":"An activity dose is useful evidence, but it does not independently establish a defensible human starting dose.","diagram":[["Animal activity","A biological observation"],["Human starting dose","A context-specific justification"]],"exampleSteps":[["Identify context","Healthy volunteers or patients?"],["Integrate evidence","Toxicology, exposure, pharmacology"],["Justify the plan","Starting dose and safeguards"]],"question":{"title":"Which argument is incomplete?","prompt":"A proposed starting dose is justified only by matching the mouse efficacy dose in mg/kg. What should the team do?","options":[["Accept it because mg/kg adjusts for species differences.","Weight adjustment alone does not resolve differences in pharmacology, kinetics, or risk.",false],["Assume a lower dose must be effective.","A lower starting dose does not guarantee activity or define later dose optimization.",false],["Develop a rationale using the relevant safety, pharmacology, exposure, and population context.","The rationale needs to connect the evidence to the actual human study.",true]],"hint":"Which human-relevant assumptions are missing from the dose match?"},"sources":[{"label":"FDA starting-dose guidance: adult healthy volunteers, final 2005","url":"https://www.fda.gov/media/72309/download"},{"label":"ICH S9: defined advanced-cancer context","url":"https://www.fda.gov/media/73161/download"}]},{"id":"people","title":"Who prepares the IND","goal":"Distinguish contracted work from transferred sponsor obligations.","concept":"An IND is a team effort. Scientific specialists generate and interpret evidence; a regulatory lead often coordinates strategy and submission; writers and publishing specialists may help prepare the documents. The sponsor has regulatory responsibilities. Hiring a vendor does not automatically transfer them.","takeaway":"Who performs a task and who holds an obligation are different questions.","exampleTitle":"A startup works with a CRO.","example":"A biotech hires a contract research organization (CRO) for a toxicology study. Toxicology and drug metabolism/pharmacokinetics specialists interpret findings and exposure; the clinical lead considers implications for the protocol. A regulatory lead coordinates the presentation. This is one possible team arrangement. Any transfer of sponsor obligations under the IND regulation must be described in writing.","worked":"Contracting a task does not automatically transfer obligations. Those not covered by a written transfer remain with the sponsor.","category":"clinical","question":{"title":"Who retains the responsibility?","prompt":"A biotech hires a vendor to assemble the electronic submission. No sponsor obligations are transferred in writing. Who retains those obligations?","options":[["The vendor, automatically, because it handles the files.","Performing a service does not automatically transfer sponsor obligations.",false],["FDA, once it receives the submission.","FDA reviews the application; receipt does not transfer the sponsor’s duties to FDA.",false],["The biotech sponsor.","Obligations not covered by a written transfer remain with the sponsor.",true]],"hint":"Separate who did the task from which obligations were transferred."},"diagram":[["Contracted task","Who performs the work?"],["Sponsor obligation","Who is responsible?"]],"exampleSteps":[["CRO","Performs an agreed task"],["Team","Interprets and integrates evidence"],["Sponsor","Retains obligations not transferred"]],"sources":[{"label":"21 CFR 312.50 and 312.52: sponsor responsibilities and CRO transfers","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-D"}]},{"id":"pre-ind","category":"clinical","title":"Ask a useful pre-IND question","goal":"Turn an uncertainty into a focused question with evidence and a proposed approach.","concept":"A pre-IND interaction can help a team discuss development questions with FDA before submission. A useful question identifies the decision, explains the evidence, and presents a proposed approach with its rationale. General requests for reassurance are harder to resolve than questions about a defined program. Feedback informs development; it is not permission to begin a trial.","takeaway":"Bring a proposed approach and the uncertainty that needs resolving.","exampleTitle":"Replace “Is our package enough?”","example":"A team has data supporting a short oral study and is considering a longer regimen. Instead of asking FDA whether the program looks good, it summarizes the proposed population and schedule, relevant existing studies, and its plan for additional support. It then asks whether that approach addresses the identified duration question.","worked":"The question is answerable because the study, supporting evidence, and proposed next step are explicit.","diagram":[["Broad reassurance","Is our program good?"],["Focused question","Does this approach address this gap?"]],"exampleSteps":[["Decision","Support a longer regimen"],["Evidence","What current studies cover"],["Proposal","Additional support and rationale"]],"question":{"title":"Which question is more useful?","prompt":"You are preparing a pre-IND briefing package. Which question best supports a focused discussion?","options":[["Given this population, regimen, evidence, and proposed study, does the approach address the identified safety gap?","A specific proposal gives the discussion a concrete decision and rationale.",true],["Can FDA confirm that the drug will succeed?","FDA cannot establish future development success from a briefing package.",false],["Can we omit the proposed clinical plan and discuss the data alone?","The intended study gives the data their development context.",false]],"hint":"Can the reviewer see both the decision and the evidence behind your proposal?"},"sources":[{"label":"FDA pre-IND consultation overview","url":"https://www.fda.gov/drugs/types-applications/investigational-new-drug-ind-application"},{"label":"FDA formal meetings guidance, final August 2026","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/formal-meetings-between-fda-and-sponsors-or-applicants-pdufa-products"}]},{"id":"map","title":"What the IND supports","goal":"Explain what an IND supports—and what an activity result cannot establish.","concept":"A development candidate is a molecule your team chooses to advance. An Investigational New Drug (IND) application brings together evidence supporting a specific proposed human study. It connects biological activity, exposure, potential harms, product quality, and the clinical plan.","takeaway":"The question is: does this evidence support this proposed study?","exampleTitle":"A tumor response is one piece of the argument.","example":"Suppose a candidate slows tumor growth in mice. That gives the team a reason to investigate further. Before proposing a human study, the team also needs to understand achieved exposure, potential harms, the material to be administered, and the study design.","worked":"Keep the useful activity result. Then identify the questions it leaves unanswered.","category":"ind","question":{"title":"A stronger result. A narrower claim.","prompt":"A candidate produces convincing tumor growth inhibition in mice. What does that result most directly support?","options":[["A biological rationale to investigate the candidate further.","Yes. Retain the activity result and define its limits. It does not answer product quality, human risk, or clinical benefit by itself.",true],["That the candidate is ready to dose in humans.","Activity is one part of the argument. Exposure, safety, product quality, and the proposed study still need support.",false],["That the same dose will work in humans.","A dose in one species does not establish human exposure, target effects, or a useful human regimen.",false]]},"diagram":[["Discovery result","A reason to develop"],["IND","Support a proposed study"]],"exampleSteps":[["Biology","Why investigate this drug?"],["Support","Exposure, safety, product quality"],["Proposed study","Dose, schedule, population, safeguards"]],"sources":[{"label":"FDA: what an IND contains","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-B/section-312.23"},{"label":"FDA: purpose of IND review","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-B/section-312.22"}]},{"id":"submission","category":"ind","title":"Assemble a traceable submission","goal":"Connect a summary claim to its source report and proposed clinical use.","concept":"An IND joins scientific and administrative material into a reviewable submission. In the eCTD, Module 1 holds regional material, Module 2 summaries, Module 3 quality, Module 4 nonclinical reports, and Module 5 clinical material. The summaries should accurately connect source findings to the proposed study. File organization supports review; it does not establish scientific adequacy.","takeaway":"Every important summary claim should be traceable to the right evidence.","exampleTitle":"A reassuring sentence loses its context.","example":"An IND summary says that a candidate was tolerated. The source report shows that exposure was low in the high-dose group. A reviewer needs the exposure result alongside the injury observations to interpret the statement. The team revises the summary to describe the actual study conditions and the remaining uncertainty, with a reference to the source report.","worked":"Traceability means preserving the meaning of the evidence, not merely placing a file in the correct folder.","diagram":[["Source report","Observations and conditions"],["Summary claim","Accurate, qualified interpretation"]],"exampleSteps":[["Find the claim","Candidate was tolerated"],["Check its support","Exposure and observed findings"],["Preserve context","Conditions, limits, source reference"]],"question":{"title":"What should be corrected?","prompt":"A summary describes a high dose as reassuring, but the study report shows little systemic exposure. Which revision best preserves the evidence?","options":[["Delete the exposure result because it complicates the story.","The exposure result is important to interpreting the observations.",false],["State the observed findings and achieved exposure, explain the limitation, and reference the report.","This lets the reviewer assess the claim in its actual experimental context.",true],["Keep the sentence because the file is in the correct eCTD module.","Correct organization does not make an unsupported inference adequate.",false]],"hint":"What information changes the meaning of the absence of observed injury?"},"sources":[{"label":"FDA eCTD overview","url":"https://www.fda.gov/drugs/electronic-regulatory-submission-and-review/electronic-common-technical-document-ectd"},{"label":"21 CFR 312.23: IND content and format","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-B/section-312.23"}]},{"id":"fda-review","category":"ind","title":"Review, questions, and holds","goal":"Distinguish submission receipt, an effective IND, and a clinical hold.","concept":"The IND goes into effect 30 days after FDA receipt unless a clinical hold applies, or earlier on FDA notification. Other trial-start requirements still apply. A hold delays or suspends the affected investigation. Responding to a hold means addressing the identified issues; sending a response does not itself lift the hold.","takeaway":"Track the actual regulatory status, not simply whether documents were sent.","exampleTitle":"A response is not a release from hold.","example":"FDA places a proposed study on clinical hold because the information is insufficient to assess risk. The sponsor submits additional evidence and a revised explanation. The team still must receive the relevant FDA notification that the investigation may proceed. It cannot treat uploading the response as an automatic end to the hold.","worked":"The response is an action by the sponsor; permission to resume the held investigation requires the applicable FDA decision.","diagram":[["Sponsor action","Submit the hold response"],["Regulatory status","Await FDA permission to proceed"]],"exampleSteps":[["Identify issue","What led to the hold?"],["Respond","Evidence and justified revisions"],["Track status","FDA notification is still needed"]],"question":{"title":"Can the held study proceed?","prompt":"The sponsor has submitted a complete response to a clinical hold. FDA has not notified the sponsor that the study may proceed. What is the correct interpretation?","options":[["The hold is automatically lifted on upload.","Submission of a response is not an automatic lifting of the hold.",false],["A favorable animal result independently lifts the hold.","An individual study result does not change the regulatory status by itself.",false],["The affected investigation remains on hold pending the relevant FDA notification.","Responding and being permitted to proceed are distinct events.",true]],"hint":"Who determines whether the identified hold issues have been resolved?"},"sources":[{"label":"21 CFR 312.40: beginning an investigation","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-C/section-312.40"},{"label":"21 CFR 312.42: clinical holds","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-C/section-312.42"}]},{"id":"review","title":"Ready for the first participant","goal":"Distinguish an effective IND from trial and participant readiness.","concept":"An IND may go into effect 30 days after FDA receipt unless a clinical hold applies, or earlier on FDA notification. That is one condition for starting. Institutional review board (IRB) approval, informed consent, and applicable participant and site requirements also matter. An effective IND is not marketing approval. The IND remains active during clinical development; safety reporting, amendments, and annual reporting continue as applicable.","takeaway":"FDA status, ethical review, and participant readiness are separate conditions.","exampleTitle":"The IND is effective. The IRB review is pending.","example":"Thirty days have elapsed since FDA received an initial IND, with no clinical hold. The IND is in effect, but the IRB has not approved the protocol. The team cannot begin this ordinary first-in-human trial while that approval is missing. The effective IND does not establish efficacy or permit marketing.","worked":"Resolve the missing IRB approval and other applicable requirements. Passage of the IND review period does not replace them.","category":"ind","question":{"title":"Check the participant’s readiness.","prompt":"The IND is effective and the IRB has approved this ordinary first-in-human study. A prospective participant has not completed informed consent. May the team give the study drug now?","options":[["Yes. IRB approval substitutes for the participant’s decision.","IRB review and individual informed consent serve different purposes. One does not replace the other.",false],["No. Legally effective informed consent is still needed before participation.","Consent is a separate prerequisite in this ordinary study. Other participant and site conditions must also be satisfied.",true],["No. Every effective IND requires another 30-day wait.","There is no automatic second 30-day wait. The missing condition here is consent.",false]],"hint":"Which decision belongs to the prospective participant?"},"diagram":[["IND status","May investigation proceed?"],["Trial readiness","Can this participant start?"]],"exampleSteps":[["IND status","Effective"],["IRB approval","Pending"],["First participant","Cannot start yet"]],"sources":[{"label":"21 CFR 312.40: conditions for beginning an investigation","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-C/section-312.40"},{"label":"21 CFR 56.103: IRB review requirements","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-56/subpart-A/section-56.103"},{"label":"21 CFR 50.20: informed consent","url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-50/subpart-B/section-50.20"},{"label":"FDA: IND annual reports and continuing responsibilities","url":"https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-application-reporting-annual-reports"}]}]};
